{
  "title": "负载与滑丝",
  "synopsis": "带负载试音暴露音量不稳问题，林岚用流程安抚周野，但校准时遭遇电位器滑丝危机。",
  "preview_blurb": "广播站接通全街网络试音，忽大忽小的破音却打破了期待，维修日志上的待校准记录成了新的考验。",
  "scenes": [
    {
      "title": "推门与试音",
      "location": "广播室",
      "dramatic_goal": "应对外部催促，开启带负载试音，接通全街网络。",
      "lines": [
        {
          "kind": "narration",
          "text": "门被猛地推开，急促的脚步声后，是周野手忙脚乱放下黄铜手铃的叮当碰撞声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎哟王大妈，您别拍门了！设备刚修好，正测试呢，马上就能听见响儿！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "把门带上。我现在推上总控推子，开启带负载试音，接通全街喇叭网络。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "好嘞，门关上了。街坊们耳朵都竖着呢，林师傅，这回看你的了。"
        }
      ]
    },
    {
      "title": "破音与日志",
      "location": "广播室",
      "dramatic_goal": "发现音量不稳问题，通过维修日志安抚周野的自责情绪。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "喂？喂？老街的街坊们，我是周野，广播站又……"
        },
        {
          "kind": "narration",
          "text": "喇叭里传出明显的音量忽大忽小和刺耳破音，林岚迅速拉下推子。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "停。带负载后阻抗变化导致输出电平不稳，必须重新校准。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "怎么又出状况？外头还等着呢，我这主持人真是连个试音都搞砸。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别自责。拿笔，在维修日志上写：带负载音量不稳，待校准。按流程来。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "带负载音量不稳，待校准。呼，写下来了。有这流程兜底，心里踏实多了。"
        }
      ]
    },
    {
      "title": "滑丝与悬念",
      "location": "广播室",
      "dramatic_goal": "拆解后盖遭遇电位器滑丝，留下工具不匹配的悬念。",
      "lines": [
        {
          "kind": "narration",
          "text": "林岚拆开调音台后盖准备校准，却传来金属滑丝的刺耳摩擦声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "糟了。校准电位器卡死，十字螺丝彻底滑丝了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "滑丝？那还能拧出来吗？这要是修不好，铃铛什么时候才能敲啊。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "常规工具咬不住。先别急，我来想办法。"
        }
      ]
